import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 300;
    static final int INF = (int)1e9;

    static class Edge {
        int to, rev, flow, capacity;
        Edge(int to, int rev, int flow, int capacity) {
            this.to = to;
            this.rev = rev;
            this.flow = flow;
            this.capacity = capacity;
        }
    }

    static List<Edge>[] adjacency = new ArrayList[MAXN];
    static {
        for (int i = 0; i < MAXN; i++) {
            adjacency[i] = new ArrayList<>();
        }
    }

    static void addEdge(int u, int v, int c, int rc) {
        Edge forward = new Edge(v, adjacency[v].size(), 0, c);
        Edge backward = new Edge(u, adjacency[u].size(), 0, rc);
        adjacency[u].add(forward);
        adjacency[v].add(backward);
    }

    static int[] distance = new int[MAXN];
    static int[] ptr = new int[MAXN];
    static int source, sink;

    static boolean bfs() {
        Arrays.fill(distance, -1);
        distance[source] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        while (!q.isEmpty() && distance[sink] == -1) {
            int u = q.poll();
            for (Edge e : adjacency[u]) {
                int v = e.to;
                if (distance[v] == -1 && e.flow < e.capacity) {
                    distance[v] = distance[u] + 1;
                    q.offer(v);
                }
            }
        }
        return distance[sink] != -1;
    }

    static int dfs(int u, int flow) {
        if (u == sink || flow == 0)
            return flow;
        for (; ptr[u] < adjacency[u].size(); ptr[u]++) {
            Edge e = adjacency[u].get(ptr[u]);
            int v = e.to;
            if (distance[v] != distance[u] + 1)
                continue;
            int pushed = dfs(v, Math.min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                adjacency[v].get(e.rev).flow -= pushed;
                return pushed;
            }
        }
        return 0;
    }

    static int maxFlow() {
        int total = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = dfs(source, INF)) > 0) {
                total += pushed;
            }
        }
        return total;
    }

    static int[] deltaX = {-1, 0, 0, 1};
    static int[] deltaY = {0, -1, 1, 0};

    static int n, m;
    static List<List<Integer>> obstacle, timeGrid, distGrid;
    static List<String> labels, responses;

    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static void bfsGrid(int r, int c, List<List<Integer>> dis, boolean check) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dis.get(i).set(j, -1);
            }
        }
        dis.get(r).set(c, 0);
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(r, c));
        while (!q.isEmpty()) {
            Point p = q.poll();
            if (check && dis.get(p.x).get(p.y) == timeGrid.get(p.x).get(p.y))
                continue;
            for (int i = 0; i < 4; i++) {
                int nx = p.x + deltaX[i];
                int ny = p.y + deltaY[i];
                if (nx < 0 || nx >= n || ny < 0 || ny >= n)
                    continue;
                if (dis.get(nx).get(ny) != -1)
                    continue;
                if (obstacle.get(nx).get(ny) == 1)
                    continue;
                if (check && timeGrid.get(nx).get(ny) > -1 && dis.get(p.x).get(p.y) + 1 > timeGrid.get(nx).get(ny))
                    continue;
                dis.get(nx).set(ny, dis.get(p.x).get(p.y) + 1);
                q.offer(new Point(nx, ny));
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());

        labels = new ArrayList<>();
        responses = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            labels.add(br.readLine());
        }
        for (int i = 0; i < n; i++) {
            responses.add(br.readLine());
        }

        obstacle = new ArrayList<>();
        timeGrid = new ArrayList<>();
        distGrid = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            obstacle.add(new ArrayList<>());
            timeGrid.add(new ArrayList<>());
            distGrid.add(new ArrayList<>());
            for (int j = 0; j < n; j++) {
                obstacle.get(i).add(0);
                timeGrid.get(i).add(0);
                distGrid.get(i).add(0);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                obstacle.get(i).set(j, labels.get(i).charAt(j) == 'Y' ? 1 : 0);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (labels.get(i).charAt(j) == 'Z') {
                    bfsGrid(i, j, timeGrid, false);
                }
            }
        }

        source = 2 * n * n + 5;
        sink = source + 1;

        for (int x = 0; x < n; x++) {
            for (int y = 0; y < n; y++) {
                char labelChar = labels.get(x).charAt(y);
                if (labelChar == 'Z' || labelChar == 'Y')
                    continue;
                addEdge(source, n * x + y, labelChar - '0', 0);
                addEdge(n * n + n * x + y, sink, responses.get(x).charAt(y) - '0', 0);
                bfsGrid(x, y, distGrid, true);
                for (int xp = 0; xp < n; xp++) {
                    for (int yp = 0; yp < n; yp++) {
                        if (distGrid.get(xp).get(yp) != -1 && distGrid.get(xp).get(yp) <= m) {
                            addEdge(n * x + y, n * n + n * xp + yp, INF, 0);
                        }
                    }
                }
            }
        }

        System.out.println(maxFlow());
    }
}
